  id: integer('id').primaryKey(),
  status: text('status').notNull(),
  couponCode: text('coupon_code'),
  placedAt: text('placed_at').notNull(),
  customerId: integer('customer_id').notNull().references((): AnySQLiteColumn => customers.id),
}, (table) => [
  index('ix_orders_customer_id').on(table.customerId),
  check('ck_orders_status', sql`${table.status} IN ('draft', 'paid', 'shipped', 'cancelled')`),
])

export const orderLines = sqliteTable('order_lines', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  quantity: real('quantity').notNull(),
  unitPrice: real('unit_price').notNull(),
  orderId: integer('order_id').notNull().references((): AnySQLiteColumn => orders.id, { onDelete: 'cascade' }),
  productId: integer('product_id').notNull().references((): AnySQLiteColumn => products.id),
